11	)
12	
13	// splitLines splits a transcript into lines without discarding anything.
14	//
15	// Aider opens its chat history with line_endings="platform", so the same parser
16	// sees CRLF on Windows and LF elsewhere, and one file can hold both when a
17	// session moves between machines. Classification is therefore always done
18	// against a \r-trimmed copy while the original bytes are preserved for storage.
19	func splitLines(data []byte) []string {
20		if len(data) == 0 {
21			return nil
22		}
23		return strings.Split(string(data), "\n")
24	}
25	
26	// classify strips the line ending and the trailing "  " that
27	// append_chat_history(linebreak=True) appends to every line it writes.
28	func classify(line string) string {
29		return strings.TrimRight(strings.TrimSuffix(line, "\r"), " \t")
30	}
31	
32	func isPromptLine(line string) bool {
33		c := classify(line)
34		return strings.HasPrefix(c, promptLinePrefix) || c == strings.TrimSpace(promptLinePrefix)
35	}
36	
37	func promptLineText(line string) string {
38		c := classify(line)
39		if t, ok := strings.CutPrefix(c, promptLinePrefix); ok {
40			return t
41		}
42		return ""
43	}
44	
45	func blockquoteText(line string) (string, bool) {
46		return strings.CutPrefix(classify(line), blockquotePrefix)
47	}
48	
49	// parseTurns splits a chat history into turns.
50	//
51	// A turn opens at a RUN of consecutive prompt lines, not at each one: aider
52	// prefixes every line of a multi-line submission with "#### " (io.py:775), so
53	// treating each prefixed line as its own turn would count a two-line prompt as
54	// two turns and desynchronize every offset in this package.
55	func parseTurns(data []byte) []turn {
56		lines := splitLines(data)
57		var turns []turn
58		var cur *turn
59		inPromptRun := false
60	
61		for _, line := range lines {
62			if isPromptLine(line) {
63				if !inPromptRun {
64					turns = append(turns, turn{Index: len(turns)})
65					cur = &turns[len(turns)-1]
66					inPromptRun = true
67				}
68				text := promptLineText(line)
69				if text == blankPromptSentinel && cur.Prompt == "" {
70					continue
71				}
72				if cur.Prompt == "" {
73					cur.Prompt = text
74				} else {
75					cur.Prompt += "\n" + text
76				}
77				continue
78			}
79			inPromptRun = false
80			if cur == nil {
81				// Preamble before the first prompt: the session banner and any
82				// startup notices, not attributable to a turn.
83				continue
84			}
85			if body, ok := blockquoteText(line); ok {
86				absorbToolLine(cur, body)
87			}
88		}
89		return turns
90	}
91	
92	func absorbToolLine(t *turn, body string) {
93		if path, ok := strings.CutPrefix(body, appliedEditPrefix); ok {
94			path = strings.TrimSpace(path)
95			if path != "" && !contains(t.ModifiedFiles, path) {
96				t.ModifiedFiles = append(t.ModifiedFiles, path)
97			}
98			return
99		}
100		if rep, ok := parseTokenReport(body); ok {
101			t.Usage.add(rep)
102		}
103	}
104	
105	func contains(haystack []string, needle string) bool {
106		for _, s := range haystack {
107			if s == needle {
108				return true
109			}
110		}
111		return false
112	}
