114	// parseTokenReport parses one usage line. Reports are independent rather than
115	// cumulative: show_usage_report zeroes message_tokens_sent/received and
116	// message_cost immediately after emitting each line (base_coder.py:2124-2126),
117	// so several reports inside one turn — which a lint or test reflection loop
118	// produces — must be summed.
119	func parseTokenReport(body string) (tokenReport, bool) {
120		m := tokenReportRe.FindStringSubmatch(body)
121		if m == nil {
122			return tokenReport{}, false
123		}
124		rep := tokenReport{
125			Sent:       parseTokenCount(m[1]),
126			CacheWrite: parseTokenCount(m[2]),
127			CacheHit:   parseTokenCount(m[3]),
128			Received:   parseTokenCount(m[4]),
129			Reports:    1,
130		}
131		if c := costReportRe.FindStringSubmatch(body); c != nil {
132			rep.MessageCost, _ = strconv.ParseFloat(c[1], 64)
133			rep.SessionCost, _ = strconv.ParseFloat(c[2], 64)
134		}
135		return rep, true
136	}
137	
138	// parseTokenCount reads one of aider's formatted token counts.
139	//
140	// The value is LOSSY above 999 and no unrounded copy exists anywhere on disk:
141	// format_tokens (utils.py:276) renders <1000 exactly, <10000 as "1.2k", and
142	// everything else as "15k". Token metadata for aider sessions is therefore
143	// exact below 1000 and rounded above it, which AGENT.md states plainly rather
144	// than presenting rounded figures as precise.
145	func parseTokenCount(s string) int {
146		s = strings.TrimSpace(s)
147		if s == "" {
148			return 0
149		}
150		mult := 1.0
151		if v, ok := strings.CutSuffix(s, "k"); ok {
152			s = v
153			mult = 1000
154		}
155		f, err := strconv.ParseFloat(s, 64)
156		if err != nil {
157			return 0
158		}
159		return int(math.Round(f * mult))
160	}
