162	// sessionIDFromBanner derives a session ID from the most recent aider run
163	// banner in the transcript.
164	//
165	// Aider records no session identifier of any kind. The banner IO writes on
166	// startup (io.py:336) is the only per-run marker in the file, so its timestamp
167	// becomes the ID. Normalized to digits and dashes because Entire validates a
168	// session ID before using it as a path component and rejects colons.
169	func sessionIDFromBanner(data []byte) string {
170		last := ""
171		for _, line := range splitLines(data) {
172			c := classify(line)
173			if !strings.HasPrefix(c, sessionBannerPrefix) {
174				continue
175			}
176			if m := bannerTimestampRe.FindStringSubmatch(c); m != nil {
177				last = m[1] + m[2] + m[3] + "-" + m[4] + m[5] + m[6]
178			}
179		}
180		return last
181	}
