183	// readTurns loads and parses a transcript, tolerating a missing file.
184	//
185	// A transcript that does not exist yet is not an error: aider creates the chat
186	// history lazily on its first append.
187	func readTurns(path string) ([]turn, error) {
188		data, err := os.ReadFile(path)
189		if err != nil {
190			if os.IsNotExist(err) {
191				return nil, nil
192			}
193			return nil, fmt.Errorf("read aider transcript: %w", err)
194		}
195		return parseTurns(data), nil
196	}
