198	// --- transcript_analyzer capability --------------------------------------
199	
200	// GetTranscriptPosition returns the number of turns in the transcript.
201	//
202	// Turn count, not line count, is the unit every offset here is expressed in,
203	// because a turn is the smallest thing that maps onto a lifecycle event.
204	func (a *Agent) GetTranscriptPosition(path string) (int, error) {
205		turns, err := readTurns(path)
206		if err != nil {
207			return 0, err
208		}
209		return len(turns), nil
210	}
