212	// ExtractModifiedFiles returns the files aider reported as edited from offset
213	// onward, plus the current turn count.
214	func (a *Agent) ExtractModifiedFiles(path string, offset int) ([]string, int, error) {
215		turns, err := readTurns(path)
216		if err != nil {
217			return nil, 0, err
218		}
219		files := []string{}
220		for _, t := range turns {
221			if t.Index < offset {
222				continue
223			}
224			for _, f := range t.ModifiedFiles {
225				if !contains(files, f) {
226					files = append(files, f)
227				}
228			}
229		}
230		return files, len(turns), nil
231	}
