233	// ExtractPrompts returns the user submissions from offset onward.
234	func (a *Agent) ExtractPrompts(sessionRef string, offset int) ([]string, error) {
235		turns, err := readTurns(sessionRef)
236		if err != nil {
237			return nil, err
238		}
239		prompts := []string{}
240		for _, t := range turns {
241			if t.Index < offset {
242				continue
243			}
244			if t.Prompt != "" {
245				prompts = append(prompts, t.Prompt)
246			}
247		}
248		return prompts, nil
249	}
