251	// ExtractSummary reports no summary. Aider writes no session summary anywhere,
252	// and inventing one from the transcript would be a guess presented as a fact.
253	func (a *Agent) ExtractSummary(_ string) (string, bool, error) {
254		return "", false, nil
255	}
