257	// --- token_calculator capability -----------------------------------------
258	
259	// CalculateTokens sums aider's own usage reports from offset onward.
260	func (a *Agent) CalculateTokens(data []byte, offset int) (protocol.TokenUsageResponse, error) {
261		turns := parseTurns(data)
262		var total tokenReport
263		for _, t := range turns {
264			if t.Index < offset {
265				continue
266			}
267			total.add(t.Usage)
268		}
269		if total.Reports == 0 {
270			return protocol.TokenUsageResponse{}, nil
271		}
272		// Aider's "sent" figure covers the whole prompt including any cached
273		// portion, so fresh input is what remains after the cache clauses. Clamped
274		// at zero: the components are independently rounded, and on a heavily
275		// cached turn that rounding can push the difference negative.
276		input := total.Sent - total.CacheWrite - total.CacheHit
277		if input < 0 {
278			input = 0
279		}
280		return protocol.TokenUsageResponse{
281			InputTokens:         input,
282			CacheCreationTokens: total.CacheWrite,
283			CacheReadTokens:     total.CacheHit,
284			OutputTokens:        total.Received,
285			APICallCount:        total.Reports,
286		}, nil
287	}
