289	// --- chunking -------------------------------------------------------------
290	
291	// ChunkTranscript splits a chat history into chunks of at most maxSize bytes,
292	// preferring turn boundaries, falling back to line boundaries inside an
293	// oversized turn and to raw byte boundaries inside an oversized line.
294	//
295	// Reassembly is plain concatenation, so a split is lossless wherever it lands.
296	// That is what allows the byte-level fallback: a JSONL chunker must reject an
297	// oversized line because splitting a JSON object corrupts it, but Markdown has
298	// no such constraint, and dropping a session because one assistant message
299	// contained a very long line would be the worse failure.
300	func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
301		if len(content) == 0 {
302			return [][]byte{}, nil
303		}
304		if maxSize <= 0 {
305			return nil, fmt.Errorf("invalid max chunk size %d", maxSize)
306		}
307		if len(content) <= maxSize {
308			return [][]byte{content}, nil
309		}
310	
311		var chunks [][]byte
312		var cur []byte
313		flush := func() {
314			if len(cur) > 0 {
315				chunks = append(chunks, cur)
316				cur = nil
317			}
318		}
319		for _, seg := range turnSegments(content) {
320			if len(cur)+len(seg) <= maxSize {
321				cur = append(cur, seg...)
322				continue
323			}
324			flush()
325			if len(seg) <= maxSize {
326				cur = append([]byte(nil), seg...)
327				continue
328			}
329			parts := splitBytes(seg, maxSize)
330			chunks = append(chunks, parts[:len(parts)-1]...)
331			cur = append([]byte(nil), parts[len(parts)-1]...)
332		}
333		flush()
334		return chunks, nil
335	}
336	
337	// ReassembleTranscript concatenates chunks. ChunkTranscript never inserts or
338	// drops a byte, so this is an exact inverse.
339	func (a *Agent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
340		n := 0
341		for _, c := range chunks {
342			n += len(c)
343		}
344		out := make([]byte, 0, n)
345		for _, c := range chunks {
346			out = append(out, c...)
347		}
348		return out, nil
349	}
350	
351	// turnSegments slices content into byte ranges that each begin at a turn
352	// boundary, preserving every byte in order.
353	func turnSegments(content []byte) [][]byte {
354		lines := splitLines(content)
355		var segments [][]byte
356		var cur []byte
357		inPromptRun := false
358	
359		for i, line := range lines {
360			raw := []byte(line)
361			if i < len(lines)-1 {
362				raw = append(raw, '\n')
363			}
364			if isPromptLine(line) {
365				if !inPromptRun && len(cur) > 0 {
366					segments = append(segments, cur)
367					cur = nil
368				}
369				inPromptRun = true
370			} else {
371				inPromptRun = false
372			}
373			cur = append(cur, raw...)
374		}
375		if len(cur) > 0 {
376			segments = append(segments, cur)
377		}
378		return segments
379	}
380	
381	// splitBytes chops b into pieces of at most size bytes, always returning at
382	// least one piece.
383	func splitBytes(b []byte, size int) [][]byte {
384		var out [][]byte
385		for len(b) > size {
386			out = append(out, b[:size])
387			b = b[size:]
388		}
389		out = append(out, b)
390		return out
391	}
