14	
15	// Agent implements the Entire external agent protocol for Aider.
16	type Agent struct{}
17	
18	// New creates an agent instance.
19	func New() *Agent { return &Agent{} }
20	
21	// Info describes the agent to Entire.
22	func (a *Agent) Info() protocol.InfoResponse {
23		return protocol.InfoResponse{
24			ProtocolVersion: protocol.ProtocolVersion,
25			Name:            "aider",
26			Type:            "Aider",
27			Description:     "Aider - AI pair programming in your terminal",
28			IsPreview:       true,
29			// Aider is unusual in writing its own state into the working tree
30			// rather than under the user's home directory. The repo-map cache is
31			// rewritten constantly, so without this every turn would report it as
32			// a change. Entries must name real DIRECTORIES only — a file listed
33			// here breaks `entire clean` for every agent, not just this one.
34			//
35			// BOTH cache versions are listed because the suffix is decided at
36			// import time by whether tree-sitter-language-pack is installed:
37			// repomap.py:33-43 sets CACHE_VERSION = 3, then 4 if USING_TSL_PACK,
38			// and names the directory ".aider.tags.cache.v{CACHE_VERSION}". Two
39			// installs of the same aider release can therefore disagree, and
40			// matching is exact per path component, so a prefix will not do. A
41			// listed directory that never exists is harmless.
42			ProtectedDirs: []string{
43				".aider.tags.cache.v3",
44				".aider.tags.cache.v4",
45			},
46			// Aider's DEFAULT history paths, declared even though install-hooks
47			// redirects them, so a user who runs aider with its stock config — or
48			// with --no-... overrides — still cannot push a chat log into a
49			// checkpoint.
50			ProtectedFiles: []string{
51				".aider.chat.history.md",
52				".aider.input.history",
53				".aider.llm.history",
54				aiderConfigFile,
55			},
56			HookNames: []string{
57				HookNameTurnEnd,
58				HookNameSessionStart,
59				HookNameSessionEnd,
60			},
61			Capabilities: protocol.DeclaredCapabilities{
62				Hooks:              true,
63				TranscriptAnalyzer: true,
64				TokenCalculator:    true,
65				UsesTerminal:       true,
66			},
67		}
68	}
