70	// Detect reports whether aider is available on PATH.
71	func (a *Agent) Detect() protocol.DetectResponse {
72		_, err := exec.LookPath("aider")
73		return protocol.DetectResponse{Present: err == nil}
74	}
75	
76	// GetSessionID returns the session identifier for a hook payload.
77	//
78	// Aider records no session ID of any kind and its notification command passes
79	// no payload, so the incoming HookInput is normally empty. The ID is derived
80	// instead from the most recent run banner in the transcript, which is the only
81	// per-run marker aider writes.
82	func (a *Agent) GetSessionID(input *protocol.HookInputJSON) string {
83		if input != nil && input.SessionID != "" {
84			return input.SessionID
85		}
86		data, err := os.ReadFile(a.transcriptPath())
87		if err != nil {
88			return ""
89		}
90		return sessionIDFromBanner(data)
91	}
92	
93	// GetSessionDir returns the directory holding aider session state.
94	func (a *Agent) GetSessionDir(repoPath string) (string, error) {
95		if override := os.Getenv("ENTIRE_TEST_AIDER_SESSION_DIR"); override != "" {
96			return override, nil
97		}
98		if repoPath == "" {
99			repoPath = protocol.RepoRoot()
100		}
101		if repoPath == "" {
102			return "", errors.New("repo path is required to resolve the aider session directory")
103		}
104		return filepath.Join(repoPath, filepath.FromSlash(sessionDirRel)), nil
105	}
106	
107	// ResolveSessionFile returns the transcript path for a session.
108	//
109	// The session ID is deliberately NOT used as a path component. Aider is
110	// configured through a static YAML file with one chat-history-file setting, so
111	// every run of a repo appends to the same transcript and runs are separated by
112	// the banner inside it rather than by separate files. Accepting the ID as a
113	// directory name would invent a layout aider never writes to.
114	func (a *Agent) ResolveSessionFile(sessionDir, _ string) string {
115		if sessionDir == "" {
116			return a.transcriptPath()
117		}
118		return filepath.Join(sessionDir, "chat.md")
119	}
120	
121	// transcriptPath returns the repo-root-anchored transcript path.
122	func (a *Agent) transcriptPath() string {
123		return filepath.Join(protocol.RepoRoot(), filepath.FromSlash(transcriptRel))
124	}
125	
126	// ReadTranscript reads the raw chat-history bytes.
127	//
128	// Bytes are returned exactly as aider wrote them, CRLF and all. Native format
129	// preservation is a protocol rule, and it matters concretely here:
130	// --restore-chat-history parses this file back in (base_coder.py:520), so a
131	// normalized copy would not round-trip.
132	func (a *Agent) ReadTranscript(sessionRef string) ([]byte, error) {
133		if sessionRef == "" {
134			sessionRef = a.transcriptPath()
135		}
136		data, err := os.ReadFile(sessionRef)
137		if err != nil {
138			if os.IsNotExist(err) {
139				return []byte{}, nil
140			}
141			return nil, fmt.Errorf("read aider transcript: %w", err)
142		}
143		return data, nil
144	}
145	
146	// ReadSession reads session data from aider's storage.
147	func (a *Agent) ReadSession(input *protocol.HookInputJSON) (protocol.AgentSessionJSON, error) {
148		ref := ""
149		if input != nil {
150			ref = input.SessionRef
151		}
152		if ref == "" {
153			ref = a.transcriptPath()
154		}
155		session := protocol.AgentSessionJSON{
156			AgentName:  "aider",
157			RepoPath:   protocol.RepoRoot(),
158			SessionRef: ref,
159			StartTime:  time.Now().UTC().Format(time.RFC3339),
160		}
161		if input != nil {
162			session.SessionID = input.SessionID
163		}
164	
165		data, err := os.ReadFile(ref)
166		if err != nil {
167			if os.IsNotExist(err) {
168				// Aider creates the chat history lazily on its first append, so an
169				// absent file is a normal early-session state, not a failure.
170				return session, nil
171			}
172			return session, fmt.Errorf("read aider transcript: %w", err)
173		}
174		session.NativeData = data
175		if session.SessionID == "" {
176			session.SessionID = sessionIDFromBanner(data)
177		}
178		for _, t := range parseTurns(data) {
179			for _, f := range t.ModifiedFiles {
180				if !contains(session.ModifiedFiles, f) {
181					session.ModifiedFiles = append(session.ModifiedFiles, f)
182				}
183			}
184		}
185		return session, nil
186	}
187	
188	// WriteSession writes a transcript back so aider can resume from it.
189	func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
190		ref := session.SessionRef
191		if ref == "" {
192			ref = a.transcriptPath()
193		}
194		if err := os.MkdirAll(filepath.Dir(ref), 0o750); err != nil {
195			return fmt.Errorf("create aider session dir: %w", err)
196		}
197		if err := os.WriteFile(ref, session.NativeData, 0o600); err != nil {
198			return fmt.Errorf("write aider transcript: %w", err)
199		}
200		return nil
201	}
202	
203	// FormatResumeCommand returns the command that resumes a session.
204	//
205	// --restore-chat-history makes aider read the transcript back in and rebuild
206	// the conversation. The session ID is not passed: aider has no flag that
207	// selects a run, so resuming replays whatever the configured chat-history-file
208	// currently holds.
209	func (a *Agent) FormatResumeCommand(sessionID string) string {
210		cmd := "aider --restore-chat-history"
211		if strings.TrimSpace(sessionID) == "" {
212			return cmd
213		}
214		return cmd + "  # session " + sessionID
215	}
