	if s := strings.TrimSpace(last.Intent); s != "" {
		sections = append(sections, "Intent: "+s)
	}
	questions := []string{"Open questions:"}
	for _, q := range last.OpenQuestions {
		if q = strings.TrimSpace(q); q != "" {
			questions = append(questions, "- "+q)
